import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type StrategyRoadmapProps = Record<string, any>;

const StrategyRoadmap: React.FC<StrategyRoadmapProps> = ({
  backgroundColor = "#f9fafb",
  transparentBackground = false,
  durationInSeconds = 10,
  mainTitle = "Brand Growth Strategy",
  accentColor = "#2563eb",
  cardBackgroundColor = "#ffffff",
  textColor = "#111827",
  descriptionColor = "#4b5563",
  items = [
    {
      stepNumber: "1️⃣",
      title: "Clarify the brand message",
      description: "What you sell and why it’s special."
    },
    {
      stepNumber: "2️⃣",
      title: "Upgrade the digital experience",
      description: "Website, product visuals, and social media."
    },
    {
      stepNumber: "3️⃣",
      title: "Create story-driven content",
      description: "Show the roasting, the popcorn, the personality behind the brand."
    }
  ]
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Outfit"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive calculations
  const titleFontSize = height * 0.08;
  const cardGap = width * 0.03;
  const cardPadding = width * 0.03;
  const borderRadius = Math.min(width, height) * 0.02;
  const stepFontSize = height * 0.06;
  const cardTitleFontSize = height * 0.035;
  const descFontSize = height * 0.025;

  // Title Animations
  const titleOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [10, 25], [-30, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: "Outfit",
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      alignItems: "center",
      padding: width * 0.05,
      boxSizing: "border-box"
    }}>
      
      {/* Main Title */}
      <div style={{
        opacity: titleOpacity,
        transform: `translateY(${titleY}px)`,
        fontSize: titleFontSize,
        fontWeight: 700,
        color: textColor,
        marginBottom: height * 0.08,
        textAlign: "center",
        transition: "none"
      }}>
        {mainTitle}
      </div>

      {/* Cards Container */}
      <div style={{
        display: "flex",
        flexDirection: "row",
        gap: cardGap,
        width: "100%",
        height: height * 0.55,
        justifyContent: "center",
        alignItems: "stretch",
        transition: "none"
      }}>
        {items.map((item, index) => {
          // Staggered delay for each card
          const delay = 20 + (index * 15);
          
          const cardSpring = spring({
            fps,
            frame: frame - delay,
            config: {
              damping: 14,
              stiffness: 100,
              mass: 0.8
            }
          });

          const cardOpacity = interpolate(cardSpring, [0, 1], [0, 1]);
          const cardY = interpolate(cardSpring, [0, 1], [100, 0]);
          const cardScale = interpolate(cardSpring, [0, 1], [0.95, 1]);

          const contentDelay = delay + 10;
          const contentSpring = spring({
            fps,
            frame: frame - contentDelay,
            config: { damping: 16, stiffness: 120 }
          });
          const contentOpacity = interpolate(contentSpring, [0, 1], [0, 1]);
          const contentY = interpolate(contentSpring, [0, 1], [20, 0]);

          return (
            <div 
              key={index} 
              style={{
                flex: 1,
                backgroundColor: cardBackgroundColor,
                borderRadius: borderRadius,
                padding: cardPadding,
                display: "flex",
                flexDirection: "column",
                boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.08)",
                opacity: cardOpacity,
                transform: `translateY(${cardY}px) scale(${cardScale})`,
                transition: "none",
                position: "relative",
                overflow: "hidden"
              }}
            >
              {/* Decorative top accent line */}
              <div style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                height: height * 0.01,
                backgroundColor: accentColor,
                transform: `scaleX(${cardSpring})`,
                transformOrigin: "left",
                transition: "none"
              }} />

              {/* Step Number / Icon */}
              <div style={{
                fontSize: stepFontSize,
                marginBottom: height * 0.03,
                opacity: contentOpacity,
                transform: `translateY(${contentY}px)`,
                transition: "none"
              }}>
                {item.stepNumber}
              </div>

              {/* Card Title */}
              <div style={{
                fontSize: cardTitleFontSize,
                fontWeight: 700,
                color: textColor,
                marginBottom: height * 0.02,
                lineHeight: 1.2,
                opacity: contentOpacity,
                transform: `translateY(${contentY}px)`,
                transition: "none"
              }}>
                {item.title}
              </div>

              {/* Card Description */}
              <div style={{
                fontSize: descFontSize,
                color: descriptionColor,
                lineHeight: 1.5,
                fontWeight: 400,
                opacity: contentOpacity,
                transform: `translateY(${contentY}px)`,
                transition: "none"
              }}>
                {item.description}
              </div>
            </div>
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default StrategyRoadmap;